package net.aptist.loft.r8probe;

import android.app.Activity;
import android.app.Instrumentation;
import android.os.Bundle;
import android.os.Process;
import java.lang.reflect.Method;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import org.json.JSONObject;

/** Test-only static metadata JNI probe. No runtime constructor/TUN/node API. */
public final class NativeProbe extends Instrumentation {
    @Override public void onCreate(Bundle arguments) {
        super.onCreate(arguments);
        start();
    }

    @Override public void onStart() {
        Bundle result = new Bundle();
        boolean passed = false;
        String stage = "LOAD_KEPT_ENGINE";
        try {
            Class<?> engine = getTargetContext().getClassLoader().loadClass("net.aptist.loft.engine.Engine");
            Method info = engine.getMethod("vpnRuntimeInfo");
            stage = "INVOKE_STATIC_GO_JNI";
            Object value = info.invoke(null);
            if (!(value instanceof String)) throw new IllegalStateException();
            String raw = (String) value;
            if (raw.length() < 2 || raw.getBytes(StandardCharsets.UTF_8).length > 4096) throw new IllegalStateException();
            stage = "VALIDATE_STATIC_CAPABILITIES";
            JSONObject json = new JSONObject(raw);
            boolean normalUid = Process.myUid() >= 10000;
            boolean linked = json.getBoolean("gvisor_built") && json.getBoolean("linked_into_mobile_data_plane");
            boolean inactive = !json.getBoolean("transport_ready") && !json.getBoolean("ipv6_forwarded");
            boolean scheduler = json.getInt("gomaxprocs") == 2;
            passed = normalUid && linked && inactive && scheduler && json.getInt("schema_version") == 1;
            result.putBoolean("ordinary_uid", normalUid);
            result.putBoolean("compiled_gvisor_linked", linked);
            result.putBoolean("transport_and_ipv6_inactive", inactive);
            result.putBoolean("gomaxprocs_two", scheduler);
            result.putInt("info_bytes", raw.getBytes(StandardCharsets.UTF_8).length);
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(raw.getBytes(StandardCharsets.UTF_8));
            StringBuilder hash = new StringBuilder();
            for (byte valueByte : digest) hash.append(String.format(java.util.Locale.ROOT, "%02x", valueByte & 255));
            result.putString("info_sha256", hash.toString());
            stage = "COMPLETE_STATIC_METADATA_ONLY";
        } catch (Throwable error) {
            result.putString("failure_type", error.getClass().getSimpleName());
        }
        result.putString("stage", stage);
        result.putBoolean("passed", passed);
        finish(passed ? Activity.RESULT_OK : Activity.RESULT_CANCELED, result);
    }
}
